import{_ as r,a,b as o,c as e,d as s,e as n,f as l,g as i,h as c}from"./chunks/x25_evo_quickstart_09.o4yPF9sk.js";import{_ as d,o as h,c as p,al as g}from"./chunks/framework.7vp1BMOE.js";const S=JSON.parse('{"title":"CUAV X25 EVO Wiring Quick Start","description":"","frontmatter":{},"headers":[],"relativePath":"uk/assembly/quick_start_cuav_x25_evo.md","filePath":"uk/assembly/quick_start_cuav_x25_evo.md"}'),u={name:"uk/assembly/quick_start_cuav_x25_evo.md"};function f(m,t,b,_,v,y){return h(),p("div",null,[...t[0]||(t[0]=[g('<h1 id="cuav-x25-evo-wiring-quick-start" tabindex="-1">CUAV X25 EVO Wiring Quick Start <a class="header-anchor" href="#cuav-x25-evo-wiring-quick-start" aria-label="Permalink to &quot;CUAV X25 EVO Wiring Quick Start&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>PX4 не розробляє цей (або будь-який інший) автопілот. Contact the <a href="https://store.cuav.net/" target="_blank" rel="noreferrer">manufacturer</a> for hardware support or compliance issues.</p></div><p>This quick start guide shows how to power the <a href="./../flight_controller/cuav_x25-evo">X25 EVO</a> flight controller and connect its most important peripherals.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The following flight controller models are applicable to this quick start guide. <a href="./../flight_controller/cuav_x25-super">CUAV X25 SUPER</a><a href="./../flight_controller/cuav_x25-mega">CUAV X25 MEGA</a></p></div><h2 id="огляд-схеми-підключення" tabindex="-1">Огляд схеми підключення <a class="header-anchor" href="#огляд-схеми-підключення" aria-label="Permalink to &quot;Огляд схеми підключення&quot;">​</a></h2><p>На зображенні нижче показано, як під&#39;єднати найважливіші датчики та периферійні пристрої (за винятком виходів мотора та сервоприводів). Ми розглянемо кожну з них докладно в наступних розділах.</p><p><img src="'+r+'" alt="wiring"></p><table tabindex="0"><thead><tr><th style="text-align:left;">Інтерфейс</th><th style="text-align:left;"><strong>Function</strong></th></tr></thead><tbody><tr><td style="text-align:left;">POWER C1/C2</td><td style="text-align:left;">Connect the PMU2 Lite to this port; this port is used for connecting the DroneCAN power module</td></tr><tr><td style="text-align:left;">M1 ~ M16</td><td style="text-align:left;">PWM signal output ports, usable for controlling motors or servos; support 3.3V/5V PWM configuration</td></tr><tr><td style="text-align:left;">RC IN</td><td style="text-align:left;">Connect remote controller receivers with one-way protocols (e.g., SBUS/DSM/PPM). Note: ELRS/CRSF receivers should be connected to any serial port, not RC IN</td></tr><tr><td style="text-align:left;">RSSI</td><td style="text-align:left;">For connecting signal strength feedback modules</td></tr><tr><td style="text-align:left;">GPS&amp;SAFETY</td><td style="text-align:left;">Connect Neo-series GPS or C-RTK-series RTK; this port includes interfaces for GPS, safety switch, and buzzer</td></tr><tr><td style="text-align:left;">GPS2</td><td style="text-align:left;">Usable for connecting additional GPS/RTK modules</td></tr><tr><td style="text-align:left;">DEBUG (DSU)</td><td style="text-align:left;">For FMU chip debugging and reading debug device information; with ArduPilot firmware, it can be configured for other serial port functions</td></tr><tr><td style="text-align:left;">ADC3V3</td><td style="text-align:left;">For analog level signal detection; the maximum detectable level signal is 3.3V</td></tr><tr><td style="text-align:left;">ADC6V6</td><td style="text-align:left;">For analog level signal detection; the maximum detectable level signal is 6.6V (PX4 is not supported.)</td></tr><tr><td style="text-align:left;">TF CARD</td><td style="text-align:left;">Insert an SD card here to enable log storage functionality</td></tr><tr><td style="text-align:left;">ETH</td><td style="text-align:left;">Ethernet port, usable for connecting Ethernet devices such as companion computers</td></tr><tr><td style="text-align:left;">I2C1/2/3</td><td style="text-align:left;">Connect external I2C devices (e.g., external compasses) for communication between the controller and I2C devices</td></tr><tr><td style="text-align:left;">TELEM1/TELEM2</td><td style="text-align:left;">Connect telemetry modules (for data transmission) to enable MAVLINK data interaction</td></tr><tr><td style="text-align:left;">CAN1/2</td><td style="text-align:left;">For communication between the controller and DroneCAN devices (e.g., connecting NEO4 SE GPS)</td></tr><tr><td style="text-align:left;">TYPE C</td><td style="text-align:left;">USB port of the controller, usable for connecting to the ground station, flashing firmware, and other operations</td></tr><tr><td style="text-align:left;">SPI6</td><td style="text-align:left;">SPI port for external expansion; generally not used</td></tr></tbody></table><h2 id="передніи-бампер" tabindex="-1">Передній бампер <a class="header-anchor" href="#передніи-бампер" aria-label="Permalink to &quot;Передній бампер&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Якщо контролер не може бути змонтований у рекомендованому/стандартному положенні (наприклад, через обмеження місця), вам потрібно буде налаштувати програмне забезпечення автопілота з орієнтацією, яку ви фактично використовували: <a href="./../config/flight_controller_orientation">Орієнтація контролера польоту</a>.</p></div><p><img src="'+a+'" alt="front"></p><h2 id="gps-компас-зумер-захиснии-вимикач-світлодіод" tabindex="-1">GPS + компас + зумер + захисний вимикач + світлодіод <a class="header-anchor" href="#gps-компас-зумер-захиснии-вимикач-світлодіод" aria-label="Permalink to &quot;GPS + компас + зумер + захисний вимикач + світлодіод&quot;">​</a></h2><p>We recommend using a CAN GPS/RTK (such as <a href="https://store.cuav.net/shop/cuav-neo-4-se-gps-module/" target="_blank" rel="noreferrer">Neo 4SE</a>); simply connect it to the <strong>CAN 1</strong> or <strong>CAN 2</strong> port.</p><p>You can also use a standard GPS/RTK module(such as <a href="https://store.cuav.net/shop/neo-3-pro/" target="_blank" rel="noreferrer">NEO3 GPS</a> (10-pin connector)) by connecting it to the <strong>GPS&amp;SAFETY</strong> port. Most commonly used GPS modules today integrate GPS, compass, safety switch, buzzer, and LED status light.</p><p>Якщо вам потрібно використовувати допоміжний GPS, підключіться до порту <strong>GPS2</strong>.</p><p>The GPS/compass should be <a href="./../assembly/mount_gps_compass">mounted on the frame</a> as far away from other electronics as possible (separating the compass from other electronics will reduce interference), with the direction markings towards the front of the vehicle (the arrow on the NEO GPS should match the arrow on the flight controller).</p><p><img src="'+o+'" alt="GPS"></p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Вбудований безпечний вимикач в GPS-модулі увімкнений <em>за замовчуванням</em> (коли включений, PX4 не дозволить вам готувати до польоту). To disable the safety, press and hold the safety switch for 1 second. Ви можете натиснути безпечний вимикач знову, щоб увімкнути безпеку та відключити транспортний засіб (це може бути корисно, якщо, з якихось причин, ви не можете вимкнути транспортний засіб за допомогою вашого пульта дистанційного керування або наземної станції).</p></div><h2 id="радіоуправління" tabindex="-1">Радіоуправління <a class="header-anchor" href="#радіоуправління" aria-label="Permalink to &quot;Радіоуправління&quot;">​</a></h2><p>Для того щоб керувати транспортним засобом <em>вручну</em>, потрібна система радіоуправління (RC) (PX4 не потребує системи радіоуправління для автономних режимів польоту).</p><p>Вам потрібно <a href="./../getting_started/rc_transmitter_receiver">вибрати сумісний передавач/приймач</a> і <em>зв&#39;язати</em> їх таким чином, щоб вони взаємодіяли (ознайомтеся з інструкціями, що додаються до вашого конкретного передавача/приймача).</p><p>Connection methods vary by remote controller and receiver type:</p><h3 id="android-remote-controllers" tabindex="-1">Android Remote Controllers <a class="header-anchor" href="#android-remote-controllers" aria-label="Permalink to &quot;Android Remote Controllers&quot;">​</a></h3><p>Take the H16 as an example:</p><p><img src="'+e+'" alt="H16 control"></p><p>Connect <strong>TELEM1/TELEM2</strong> to the UART0 port of the H16 remote controller, and link the H16’s SBUS pin to the <strong>RC IN</strong> port.</p><h3 id="sbus-dsm-ppm-protocol-receivers" tabindex="-1">SBUS/DSM/PPM Protocol Receivers <a class="header-anchor" href="#sbus-dsm-ppm-protocol-receivers" aria-label="Permalink to &quot;SBUS/DSM/PPM Protocol Receivers&quot;">​</a></h3><p><img src="'+s+'" alt="SBUS/DSM/PPM control"></p><p>Use wires to connect the receiver to the <strong>RC IN</strong> port at the rear of the controller.</p><h3 id="elrs-crsf-receivers" tabindex="-1">ELRS/CRSF Receivers <a class="header-anchor" href="#elrs-crsf-receivers" aria-label="Permalink to &quot;ELRS/CRSF Receivers&quot;">​</a></h3><p><img src="'+n+'" alt="ELRS/CRSF control"></p><p>Connect the <a href="./../telemetry/crsf_telemetry">ELRS/CRSF</a> receiver to any UART serial port of the X25 EVO (e.g., <strong>TELEM2</strong>).</p><h2 id="power" tabindex="-1">Power <a class="header-anchor" href="#power" aria-label="Permalink to &quot;Power&quot;">​</a></h2><p>The X25 EVO comes standard with the PMU2 Lite power module, which supports 20–70V input and can measure a maximum current of 220A. It can be directly connected to the <strong>Power C1/C2</strong> port of the X25 EVO and is plug-and-play (no configuration required).</p><p><img src="'+l+'" alt="Power"></p><h2 id="телеметріина-радіо-система" tabindex="-1">Телеметрійна (радіо) система <a class="header-anchor" href="#телеметріина-радіо-система" aria-label="Permalink to &quot;Телеметрійна (радіо) система&quot;">​</a></h2><p><a href="./../telemetry/">Telemetry system</a> allows you to communicate with the unmanned system via ground station software, enabling you to monitor and control the UAV’s status during flight. Connect the on-board unit of the telemetry system to the <strong>TELEM1</strong> or <strong>TELEM2</strong> port.</p><p>You can also purchase telemetry radios from the <a href="https://store.cuav.net/category/telemetry/" target="_blank" rel="noreferrer">CUAV store</a>.</p><p><img src="'+e+'" alt="Telemetry system"></p><h2 id="sd-карта" tabindex="-1">SD-карта <a class="header-anchor" href="#sd-карта" aria-label="Permalink to &quot;SD-карта&quot;">​</a></h2><p>Картки SD настійно рекомендується, оскільки вони потрібні для <a href="./../getting_started/flight_reporting">запису та аналізу даних польоту</a>, для виконання завдань та використання апаратного засобу UAVCAN bus. An SD card is already installed on X25 EVO when it leaves the factory.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Для отримання додаткової інформації див. <a href="./../getting_started/px4_basic_concepts#sd-cards-removable-memory">Основні концепції &gt; SD-карти (знімна пам&#39;ять)</a>.</p></div><h2 id="мотори-сервоприводи" tabindex="-1">Мотори/Сервоприводи <a class="header-anchor" href="#мотори-сервоприводи" aria-label="Permalink to &quot;Мотори/Сервоприводи&quot;">​</a></h2><p>Motors/servos are connected to the <strong>M1~M16</strong> ports in the order specified for your vehicle in the <a href="./../airframes/airframe_reference">Airframe Reference</a>.</p><p><img src="'+i+'" alt="Motors"></p><h2 id="джерело-живлення-для-сервоприводу" tabindex="-1">Джерело живлення для сервоприводу <a class="header-anchor" href="#джерело-живлення-для-сервоприводу" aria-label="Permalink to &quot;Джерело живлення для сервоприводу&quot;">​</a></h2><p>The X25 EVO does not supply power to servos. If you need to power servos:</p><ol><li>Connect a BEC to the positive and negative terminals of any column among <strong>M1 ~ M16</strong> (the positive and negative terminals of <strong>M1 ~ M16</strong> are interconnected).</li><li>Then connect the servos to the same column.</li></ol><p><img src="'+c+'" alt="servo power supply"></p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Напруга шини живлення повинна бути відповідною для використаного сервоприводу!</p></div><h2 id="інші-периферіині-пристроі" tabindex="-1">Інші периферійні пристрої <a class="header-anchor" href="#інші-периферіині-пристроі" aria-label="Permalink to &quot;Інші периферійні пристрої&quot;">​</a></h2><p>Підключення та конфігурація додаткових/менш поширених компонентів описано в темах для окремих <a href="./../peripherals/">периферійних пристроїв</a>.</p><h2 id="налаштування" tabindex="-1">Налаштування <a class="header-anchor" href="#налаштування" aria-label="Permalink to &quot;Налаштування&quot;">​</a></h2><p>Загальну інформацію про конфігурацію описано в: <a href="./../config/">Конфігурація автопілота</a>.</p><p>QuadPlane-specific configuration is covered here: <a href="./../config_vtol/vtol_quad_configuration">QuadPlane VTOL Configuration</a></p><h2 id="подальша-інформація" tabindex="-1">Подальша інформація <a class="header-anchor" href="#подальша-інформація" aria-label="Permalink to &quot;Подальша інформація&quot;">​</a></h2><ul><li><a href="https://doc.cuav.net/" target="_blank" rel="noreferrer">Документація CUAV</a> (CUAV)</li><li><a href="./../flight_controller/cuav_x25-evo">X25 EVO</a> (PX4 Doc Overview page)</li><li><a href="./../flight_controller/cuav_x25-super">X25 SUPER</a> (PX4 Doc Overview page)</li><li>[<a href="./../flight_controller/cuav_x25-mega">X25 MEGA</a>] (PX4 Doc Overview page)</li></ul>',57)])])}const C=d(u,[["render",f]]);export{S as __pageData,C as default};
